package com.chronos.education.scheduling.model;
import jakarta.persistence.*; import lombok.*;
@Entity @Getter @Setter @NoArgsConstructor @Table(name="edu_research_result")
public class ResearchResult { @Id @Column(length=64) private String id; @Column(name="activity_id",nullable=false,length=64) private String activityId; @Column(nullable=false,length=200) private String title; @Column(columnDefinition="text") private String content; @Column(name="file_id",length=64) private String fileId; @Column(nullable=false,length=24) private String status="DRAFT"; @Column(name="result_type",length=32) private String resultType; @Column(name="published_at") private java.time.LocalDateTime publishedAt; @Column(name="review_record_id",length=64) private String reviewRecordId; @Version @Column(name="row_version",nullable=false) private long rowVersion; }
